{
 "app_name": "file_system",
 "api_name": "show_directory",
 "path": "/file_system/directory",
 "method": "GET",
 "description": "Show a list of files and/or sub-directories, optionally recursively, in a directory.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from file_system app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "directory_path",
   "type": "string",
   "required": false,
   "description": "Path of the directory. Path can be absolute, starting with '/', or relative to the user's home directory, starting with '~/'.",
   "default": "/",
   "constraints": [
    "length >= 1"
   ]
  },
  {
   "name": "substring",
   "type": "string",
   "required": false,
   "description": "If passed, only files and sub-directories containing the given substring (ignoring case) will be shown.",
   "default": null,
   "constraints": []
  },
  {
   "name": "entry_type",
   "type": "string",
   "required": false,
   "description": "Whether to show all files and sub-directories, only files, or only sub-directories.",
   "default": "all",
   "constraints": [
    "value in ['all', 'files', 'directories']"
   ]
  },
  {
   "name": "recursive",
   "type": "boolean",
   "required": false,
   "description": "Whether to show files recursively.",
   "default": true,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": [
   "string"
  ],
  "failure": {
   "message": "string"
  }
 }
}

{
 "app_name": "supervisor",
 "api_name": "complete_task",
 "path": "/supervisor/message",
 "method": "POST",
 "description": "Mark the currently active task as complete with the given answer.",
 "parameters": [
  {
   "name": "answer",
   "type": "number | integer | string",
   "required": false,
   "description": "The answer to the task instruction. Pass it if and only if the task requests an answer, e.g., 'How many songs are in the Spotify queue?'. The answer must be concise, such as a number, a yes/no, or a specific entity, name, etc, e.g., '10' in this case. If the task is not a question, e.g., 'Start my Spotify music player.', the answer must be left to the default value, i.e., None.",
   "default": null,
   "constraints": []
  },
  {
   "name": "status",
   "type": "string",
   "required": false,
   "description": "Mark the task complete.",
   "default": "success",
   "constraints": [
    "value in ['success', 'fail']"
   ]
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string"
  },
  "failure": {
   "message": "string"
  }
 }
}
